def solve(nums):
    a = sorted(nums)
    out = []
    n = len(a)
    for i in range(n - 2):
        if i > 0 and a[i] == a[i - 1]:
            continue
        l = i + 1
        r = n - 1
        while l < r:
            t = a[i] + a[l] + a[r]
            if t < 0:
                l += 1
            elif t > 0:
                r -= 1
            else:
                out.append([a[i], a[l], a[r]])
                l += 1
                r -= 1
                while l < r and a[l] == a[l - 1]:
                    l += 1
                while l < r and a[r] == a[r + 1]:
                    r -= 1
    return sorted(out)

