def solve(lists):
    import heapq
    heap = []
    for i, l in enumerate(lists):
        if l:
            heap.append((l[0], i, 0))
    heapq.heapify(heap)
    out = []
    while heap:
        v, i, j = heapq.heappop(heap)
        out.append(v)
        if j + 1 < len(lists[i]):
            heapq.heappush(heap, (lists[i][j + 1], i, j + 1))
    return out

